const fs = require('node:fs');
const crypto = require('node:crypto');
const path = require('node:path');
const input = 'products/services/liveca-invoice-pilot/raw/contact.html';
const output = 'products/services/liveca-invoice-pilot/director-contact-audience.json';
const source = fs.readFileSync(input);
const sha256 = crypto.createHash('sha256').update(source).digest('hex');
if (sha256 !== '0d557c5233ef74b919a232fa5b6743358e86958391cf0dd120ce3a929654d8aa') throw new Error('Contact capture differs from TASK-179572680201');
const html = source.toString('utf8').replace(/<(script|style)\b[^>]*>[\s\S]*?<\/\1>/gi, ' ');
const plain = value => value.replace(/<[^>]*>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/\s+/g, ' ').trim();
const text = plain(html);
const terms = /\b(?:supplier|vendor|partnership|general inqui(?:ry|ries)|contact us|get a price|prospective client|book a call|accounting services|how can we help|referral)\b/gi;
const excerpts = [...text.matchAll(terms)].slice(0, 30).map(match => text.slice(Math.max(0, match.index - 90), match.index + match[0].length + 120));
const forms = [...html.matchAll(/<form\b[^>]*>([\s\S]*?)<\/form>/gi)].slice(0, 12).map(match => ({ visibleText: plain(match[1]).slice(0, 3000), fields: [...match[1].matchAll(/<(?:input|textarea|select)\b[^>]*>/gi)].slice(0, 35).map(field => field[0].match(/\b(?:name|placeholder|aria-label|type)\s*=\s*(?:"[^"]*"|'[^']*')/gi) || []) }));
const report = { source: 'https://www.liveca.ca/contact', sha256, excerpts, forms, iframeCount: [...html.matchAll(/<iframe\b/gi)].length, scope: 'Navigation excerpts and static form fields from the saved capture. Verify original context before concluding which inquiries the route accepts. Embedded or dynamic forms may be absent from this extraction. No form was submitted.' };
fs.mkdirSync(path.dirname(output), { recursive: true });
fs.writeFileSync(output, JSON.stringify(report, null, 2) + '\n');
console.log(JSON.stringify(report, null, 2));
